ices.AddSingleton<IDocumentaryFfprobeResultParser,DocumentaryFfprobeResultParser>();services.TryAddScoped<ExistingFfprobeDocumentaryMediaProbe>();services.TryAddScoped<IDocumentaryFfprobeProbe>(sp=>sp.GetRequiredService<ExistingFfprobeDocumentaryMediaProbe>());services.TryAddScoped<IDocumentaryMediaProbe>(sp=>sp.GetRequiredService<ExistingFfprobeDocumentaryMediaProbe>());services.AddSingleton<IDocumentaryProductionFailureNormalizer,DocumentaryProductionFailureNormalizer>();services.AddSingleton<IDocumentaryProductionDiagnosticsWriter,DocumentaryProductionDiagnosticsWriter>();services.AddSingleton<IDocumentaryVisualProviderRouter,DocumentaryVisualProviderRouter>();services.AddSingleton<IDocumentaryVisualFallbackPolicy,DocumentaryVisualFallbackPolicy>();services.AddSingleton<IDocumentaryImageInspector,DocumentaryImageInspector>();services.AddScoped<IDocumentaryProductionVisualAdapter,ExistingDocumentaryVisualProductionAdapter>();services.AddSingleton<IDocumentaryNarrationVoiceResolver,DocumentaryNarrationVoiceResolver>();services.AddSingleton<IDocumentaryNarrationAudioInspector,DocumentaryNarrationAudioInspector>();services.AddSingleton<IDocumentaryNarrationAudioNormalizer,ExistingDocumentaryNarrationAudioNormalizer>();services.AddScoped<IDocumentaryNarrationProviderBinding,AzureSpeechDocumentaryNarrationProviderBinding>();services.AddScoped<IDocumentaryProductionNarrationAdapter,ExistingAzureSpeechDocumentaryNarrationAdapter>();services.AddSingleton<IDocumentaryNarrationSynthesisResultMapper,DocumentaryNarrationSynthesisResultMapper>();services.AddSingleton<IDocumentarySubtitleInspector,DocumentarySubtitleInspector>();services.AddScoped<IDocumentarySubtitleProviderBinding,ExistingDocumentarySubtitleProviderBinding>();services.AddScoped<IDocumentaryProductionSubtitleAdapter,ExistingDocumentarySubtitleAdapter>();services.AddSingleton<IDocumentarySubtitleGenerationResultMapper,DocumentarySubtitleGenerationResultMapper>();services.TryAddScoped<IProcessRunner,ProcessRunner>();services.AddSingleton<FfmpegArgumentBuilder>();services.AddSingleton<IDocumentarySceneDependencyResolver,DocumentarySceneDependencyResolver>();services.AddScoped<IDocumentarySceneCompositionProviderBinding,ExistingFFmpegDocumentarySceneProviderBinding>();services.AddSingleton<IDocumentarySceneVideoInspector,DocumentarySceneVideoInspector>();services.AddScoped<IDocumentaryProductionSceneCompositionAdapter,ExistingDocumentarySceneCompositionAdapter>();services.AddSingleton<IDocumentarySceneCompositionResultMapper,DocumentarySceneCompositionResultMapper>();services.AddSingleton<IDocumentaryVariantDependencyResolver,DocumentaryVariantDependencyResolver>();services.AddSingleton<IDocumentaryVariantCompatibilityValidator,DocumentaryVariantCompatibilityValidator>();services.AddScoped<IDocumentaryVariantCompositionProviderBinding,ExistingFFmpegDocumentaryVariantProviderBinding>();services.AddSingleton<IDocumentaryVariantVideoInspector,DocumentaryVariantVideoInspector>();services.AddScoped<IDocumentaryProductionVariantCompositionAdapter,ExistingDocumentaryVariantCompositionAdapter>();services.AddSingleton<IDocumentaryVariantCompositionResultMapper,DocumentaryVariantCompositionResultMapper>();services.AddSingleton<IDocumentaryMediaVerificationPolicyResolver,DocumentaryMediaVerificationPolicyResolver>();services.AddSingleton<IDocumentaryMediaVerificationEvaluator,DocumentaryMediaVerificationEvaluator>();services.AddScoped<IDocumentaryMediaVerificationProviderBinding,ExistingFFprobeDocumentaryMediaVerificationProviderBinding>();services.AddScoped<IDocumentaryProductionMediaVerificationAdapter,DocumentaryProductionMediaVerificationAdapter>();services.AddSingleton<IDocumentaryMediaVerificationResultMapper,DocumentaryMediaVerificationResultMapper>();services.AddScoped<IDocumentaryProductionAdapterRegistry,DocumentaryProductionAdapterRegistry>();services.AddSingleton<IDocumentaryVisualGenerationResultMapper,DocumentaryVisualGenerationResultMapper>();services.AddSingleton<IDocumentaryProductionExecutionRecordMapper,DocumentaryProductionExecutionRecordMapper>();services.AddScoped<IDocumentaryProductionExecutionContextFactory,DocumentaryProductionExecutionContextFactory>();services.AddScoped<IDocumentaryProductionWorkspaceManager,DocumentaryProductionWorkspaceManager>();services.AddScoped<IDocumentaryPhysicalArtifactRegistry,DocumentaryPhysicalArtifactRegistry>();services.AddScoped<IDocumentaryPhysicalArtifactInspector,DocumentaryPhysicalArtifactInspector>();services.AddScoped<IDocumentaryProductionExecutionHost,DocumentaryProductionExecutionHost>();return services;}}
